insert into prep.summaries (id, grp, free, sort, data) values
  ('b3-thai-phon', 'B3', false, 55, '{"group":"B3","topics":["B3-THAI"],"id":"b3-thai-phon","subtopics":["B3-THAI-PHON"],"icon":"🔤","title":"ระบบเสียงและอักษรไทย","hub":"เสียงในภาษา","hubSub":"พยัญชนะ · สระ · วรรณยุกต์ · ไตรยางศ์","intro":"หมวดนี้คนตอบถูกแค่ราว 4 ใน 10 ข้อ: นับพยางค์ เสียงพยัญชนะท้าย และการผันวรรณยุกต์ ต้องนับจาก \"เสียง\" ไม่ใช่ \"รูป\"","branches":[{"id":"count","icon":"🧮","tone":"pink","title":"รูป vs เสียง","big":"44 · 21 · 4","unit":"รูป","must":true,"sub":"พยัญชนะ 44 รูป 21 เสียง · สระ 21 รูป · วรรณยุกต์ 4 รูป 5 เสียง","ask":"พยัญชนะ สระ วรรณยุกต์ มีกี่รูปกี่เสียง","blocks":[{"k":"table","head":["","รูป","เสียง"],"rows":[["พยัญชนะ","44 รูป (ใช้จริง 42 · ฃ ฅ เลิกใช้)","21 เสียง"],["สระ","21 รูป","21 เสียง: สระเดี่ยว 18 (สั้น 9 ยาว 9) + สระประสม 3 (เอีย เอือ อัว)"],["วรรณยุกต์","4 รูป: ่ ้ ๊ ๋","5 เสียง: สามัญ เอก โท ตรี จัตวา"]]},{"k":"list","items":[{"icon":"➕","t":"สระเกิน 8 ตัว","d":"อำ ใอ ไอ เอา ฤ ฤๅ ฦ ฦๅ: ไม่ใช่เสียงใหม่ เป็นสระผสมพยัญชนะ (อำ = อะ+ม · ไอ ใอ = อะ+ย · เอา = อะ+ว · ฤ = ร+อึ/อิ/เออ)"},{"icon":"📚","t":"บางตำรานับสระประสม 6 เสียง","d":"แยกเสียงสั้น เอียะ เอือะ อัวะ ออกมา รวมเป็น 24 เสียง ข้อสอบส่วนใหญ่ใช้ 21 เสียง"}]},{"k":"oops","t":"ข้อสอบชอบถาม \"เสียง\" แต่ตัวเลือกเป็น \"รูป\": พยัญชนะ 44 คือรูป ส่วนเสียงมี 21"}]},{"id":"class","icon":"🎚️","tone":"mint","title":"อักษรสามหมู่","big":"9 · 11 · 24","unit":"ตัว","must":true,"sub":"กลาง 9 · สูง 11 · ต่ำ 24 (คู่ 14 · เดี่ยว 10)","ask":"อักษรกลาง สูง ต่ำ มีกี่ตัว ตัวไหนบ้าง","blocks":[{"k":"table","head":["หมู่","ตัวอักษร","ท่องจำ"],"rows":[["อักษรกลาง 9","ก จ ฎ ฏ ด ต บ ป อ","ไก่ จิก เด็ก ตาย (ฎ ฏ) บน ปาก โอ่ง"],["อักษรสูง 11","ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห","ผี ฝาก ถุง ข้าว สาร ให้ ฉัน"],["อักษรต่ำเดี่ยว 10","ง ญ ณ น ม ย ร ล ว ฬ","งู ใหญ่ นอน อยู่ ณ ริม วัด โม ฬี โลก"],["อักษรต่ำคู่ 14","ค ฅ ฆ ช ฌ ซ ฑ ฒ ท ธ พ ภ ฟ ฮ","มีเสียงคู่กับอักษรสูง เช่น ค–ข · ท–ถ · พ–ผ · ซ–ส · ฮ–ห"]]},{"k":"memo","t":"อักษรต่ำเดี่ยว = ไม่มีคู่อักษรสูง จึงต้องใช้ ห/อ นำเมื่ออยากได้เสียงเอกหรือจัตวา (หนู หมา อย่า)"}]},{"id":"tone","icon":"🎵","tone":"sky","title":"คำเป็น คำตาย & การผัน","big":"5","unit":"เสียง","hot":true,"sub":"อักษรกลางคำเป็นผันได้ครบ 5 เสียง","ask":"อักษรหมู่ไหนผันได้ครบ 5 เสียง และคำตายคืออะไร","blocks":[{"k":"pairs","items":[{"a":"คำเป็น","b":"สระเสียงยาวไม่มีตัวสะกด · มีตัวสะกดแม่ กง กน กม เกย เกอว · อำ ไอ ใอ เอา"},{"a":"คำตาย","b":"สระเสียงสั้นไม่มีตัวสะกด (ยกเว้น อำ ไอ ใอ เอา) · มีตัวสะกดแม่ กก กด กบ"}]},{"k":"table","head":["อักษร","คำเป็น (พื้นเสียง)","คำตาย (พื้นเสียง)"],"rows":[["กลาง","สามัญ · ผันได้ 5 เสียง (กา ก่า ก้า ก๊า ก๋า)","เอก (กะ จด)"],["สูง","จัตวา · ผัน 3 เสียง (ขา ข่า ข้า)","เอก (ขะ ขด)"],["ต่ำ","สามัญ · ผัน 3 เสียง (คา ค่า=โท ค้า=ตรี)","สระสั้น = ตรี (คะ) · สระยาว = โท (คาด)"]]},{"k":"oops","t":"อักษรต่ำ ไม้เอกให้เสียงโท ไม้โทให้เสียงตรี: \"ค่า\" เสียงโท \"ค้า\" เสียงตรี ห้ามดูรูปแล้วตอบเสียงทันที"}]},{"id":"final","icon":"🔚","tone":"lem","title":"ตัวสะกด 8 มาตรา","big":"8","unit":"มาตรา","hot":true,"sub":"กก กด กบ กง กน กม เกย เกอว + แม่ ก กา (ไม่มีตัวสะกด)","ask":"มาตราตัวสะกดมีกี่มาตรา","blocks":[{"k":"table","head":["มาตรา","เสียงท้าย","ตัวอย่างตัวสะกด"],"rows":[["แม่กก","/k/","ก ข ค ฆ · สุข เมฆ"],["แม่กด","/t/","ด จ ช ซ ฎ ฏ ฐ ฑ ฒ ต ถ ท ธ ศ ษ ส · กิจ ครุฑ รส"],["แม่กบ","/p/","บ ป พ ฟ ภ · ภาพ กราฟ"],["แม่กง","/ŋ/","ง"],["แม่กน","/n/","น ญ ณ ร ล ฬ · กาล พร บุญ"],["แม่กม","/m/","ม"],["แม่เกย","/j/","ย"],["แม่เกอว","/w/","ว"]]},{"k":"oops","t":"ไอ ใอ เอา อำ มีเสียงพยัญชนะท้ายแฝงอยู่ (ไป = ป-อะ-ย · เอา = อ-อะ-ว · อำ = อ-อะ-ม) ข้อ \"ไม่มีเสียงพยัญชนะท้าย\" ต้องตัดคำพวกนี้ทิ้ง เช่น \"หมาตัวนี้ดุ\" ไม่มีเสียงท้ายเลย แต่ \"หมูไปไก่มา\" มี (ไป ไก่)"}]},{"id":"cluster","icon":"🔗","tone":"lil","title":"ควบกล้ำ อักษรนำ & พยางค์","big":"ร ล ว","unit":"ควบแท้","hot":true,"sub":"ควบแท้ ร ล ว · ควบไม่แท้ ทร→ซ · อักษรนำออกเสียงตามตัวนำ","ask":"ควบแท้กับควบไม่แท้ต่างกันอย่างไร","blocks":[{"k":"pairs","items":[{"a":"ควบกล้ำแท้","b":"พยัญชนะ + ร ล ว ออกเสียงทั้ง 2 ตัว: กราบ ปลา ขวาน"},{"a":"ควบกล้ำไม่แท้","b":"จร ซร ศร สร ออกเสียงตัวหน้า (จริง ไซร้ เศร้า สร้าง) · ทร ออกเสียง ซ (ทราย ทราบ ทรง)"},{"a":"อักษรนำ (ห นำ)","b":"ห นำอักษรต่ำเดี่ยว ออกเสียงตามหมู่ ห: หมา หนู ไหว"},{"a":"อักษรนำ (อ นำ ย)","b":"มี 4 คำ: อย่า อยู่ อย่าง อยาก"},{"a":"อักษรนำออกเสียง 2 พยางค์","b":"ขนม (ขะ-หนม) สนุก (สะ-หนุก) ตลาด (ตะ-หลาด)"}]},{"k":"list","items":[{"icon":"🔢","t":"นับพยางค์ตามเสียงอ่าน","d":"มีพระบรมราชโองการ = มี-พระ-บอ-รม-มะ-ราด-ชะ-โอง-กาน = 9 พยางค์ · ประวัติศาสตร์ = ประ-หวัด-ติ-สาด = 4"},{"icon":"🔊","t":"ฑ อ่านได้ 2 เสียง","d":"อ่าน ท: บัณฑิต มณฑล ขัณฑสกร · อ่าน ด: มณฑป บัณเฑาะว์ บุณฑริก"}]},{"k":"memo","t":"นับพยางค์ = อ่านออกเสียงช้า ๆ แล้วนับครั้งที่เปล่งเสียง ไม่ใช่นับคำหรือนับรูปสระ"}]}]}'::jsonb),
  ('b3-thai-word', 'B3', false, 56, '{"group":"B3","topics":["B3-THAI"],"id":"b3-thai-word","subtopics":["B3-THAI-WORD"],"icon":"🧱","title":"การสร้างคำ","hub":"สร้างคำ","hubSub":"มูล · ประสม · ซ้อน · ซ้ำ · สมาส · สนธิ · แผลง","intro":"หมวดที่คนตอบถูกน้อยที่สุดของวิชาเอก (ราว 1 ใน 3) ส่วนใหญ่พลาดเรื่องสมาสกับสนธิ","branches":[{"id":"types","icon":"🧩","tone":"pink","title":"วิธีสร้างคำแบบไทย","big":"4","unit":"แบบ","must":true,"sub":"คำมูล · คำประสม · คำซ้อน · คำซ้ำ","ask":"คำมูล คำประสม คำซ้อน คำซ้ำ ต่างกันอย่างไร","blocks":[{"k":"table","head":["ชนิด","หลักสังเกต","ตัวอย่าง"],"rows":[["คำมูล","คำเดียวที่แยกไม่ได้ (แยกแล้วไม่มีความหมาย หรือความหมายไม่เกี่ยว)","นาฬิกา กระดาษ บ้าน"],["คำประสม","คำมูล 2 คำขึ้นไปรวมกัน ได้ความหมายใหม่ ยังเกี่ยวกับคำเดิม","แม่น้ำ พ่อมด ลูกกรง ช่างฟิต รถไฟ"],["คำซ้อน","คำความหมายเหมือน/คล้าย/ตรงข้าม หรือเสียงคล้ายกัน มาซ้อนกัน","บ้านเรือน ดีชั่ว เกะกะ จุกจิก"],["คำซ้ำ","คำเดิมซ้ำ ใช้ไม้ยมก ๆ","เด็ก ๆ ดำ ๆ ไปไหน ๆ"]]},{"k":"pairs","items":[{"a":"คำซ้อนเพื่อความหมาย","b":"ความหมายเหมือน (ข้าทาส) · คล้าย (เสื่อสาด) · ตรงข้าม (ผิดชอบ)"},{"a":"คำซ้อนเพื่อเสียง","b":"เสียงคล้ายกันให้คล่องปาก: เกะกะ อึกทึก ตุกติก"}]},{"k":"oops","t":"คำประสมยืมภาษาอื่นได้ (ช่างฟิต = ไทย + อังกฤษ) ไม่ต้องเป็นคำไทยล้วน"}]},{"id":"repeat","icon":"🔁","tone":"mint","title":"คำซ้ำ","big":"ๆ","unit":"","hot":true,"sub":"พหูพจน์ · เน้น · ไม่เจาะจง · ความหมายเปลี่ยน","ask":"คำซ้ำให้ความหมายแบบไหนได้บ้าง","blocks":[{"k":"pairs","items":[{"a":"เป็นพหูพจน์","b":"เด็ก ๆ วิ่งเล่น · เพื่อน ๆ มาหา"},{"a":"เน้นความหมาย","b":"ดำ ๆ (ดำมาก) · ดี๊ดี (เปลี่ยนเสียงเน้นมาก)"},{"a":"ไม่เจาะจง","b":"ไปไหน ๆ ก็ได้ · ใคร ๆ ก็รู้"},{"a":"แยกเป็นส่วน ๆ","b":"ทำเป็นข้อ ๆ · อ่านเป็นตอน ๆ"},{"a":"ความหมายเปลี่ยน (เป็นสำนวน)","b":"หมู ๆ (ง่าย) · ไป ๆ มา ๆ · เล่น ๆ (ไม่จริงจัง)"},{"a":"บอกเวลาใกล้","b":"มาใหม่ ๆ · กินเสร็จใหม่ ๆ"}]},{"k":"memo","t":"ซ้ำแล้วแปลว่า \"หลาย\" = พหูพจน์ · ซ้ำแล้วแปลว่า \"เพิ่งจะ\" (ใหม่ ๆ) = บอกเวลา ไม่ใช่พหูพจน์"}]},{"id":"samas","icon":"🔗","tone":"sky","title":"คำสมาส","big":"หลัง→หน้า","unit":"","must":true,"hot":true,"sub":"บาลีสันสกฤต + บาลีสันสกฤต · แปลจากหลังไปหน้า · อ่านต่อเสียง","ask":"คำสมาสมีลักษณะอย่างไร","blocks":[{"k":"list","items":[{"icon":"1️⃣","t":"ต้องเป็นคำบาลีหรือสันสกฤตทั้งหมด","d":"ราชการ (ราช+การ) ✓ · ราชวัง ✗ (วัง เป็นคำไทย) · ผลไม้ ✗ (ไม้ เป็นคำไทย)"},{"icon":"2️⃣","t":"คำหลักอยู่หลัง แปลจากหลังไปหน้า","d":"ราชการ = การของพระราชา · วิทยาศาสตร์ = ศาสตร์ว่าด้วยความรู้"},{"icon":"3️⃣","t":"อ่านออกเสียงต่อเนื่องระหว่างคำ","d":"ประวัติศาสตร์ = ประ-หวัด-ติ-สาด · คุณวุฒิ = คุน-นะ-วุด"},{"icon":"4️⃣","t":"คำแรกไม่ใส่การันต์ ไม่ใส่ไม้หันอากาศ","d":"แพทย + ศาสตร์ = แพทยศาสตร์ (ไม่ใช่ แพทย์ศาสตร์)"}]},{"k":"oops","t":"\"พระ\" นำหน้า ไม่ทำให้เป็นสมาสเสมอไป: พระราชวัง พระเก้าอี้ ไม่ใช่สมาส เพราะ วัง เก้าอี้ ไม่ใช่บาลีสันสกฤต"}]},{"id":"sandhi","icon":"🧪","tone":"lem","title":"คำสนธิ","big":"3","unit":"แบบ","hot":true,"sub":"สระสนธิ · พยัญชนะสนธิ · นิคหิตสนธิ","ask":"สนธิมีกี่แบบ ยกตัวอย่าง","blocks":[{"k":"table","head":["แบบ","การกลืนเสียง","ตัวอย่าง"],"rows":[["สระสนธิ","สระท้ายคำหน้า + สระต้นคำหลัง กลืนเป็นเสียงเดียว","ราช+อุปโภค = ราชูปโภค · ปรม+อินทร์ = ปรมินทร์ · มหา+อรรณพ = มหรรณพ · วิทยา+อาลัย = วิทยาลัย · ธนู+อาคม = ธันวาคม · มหา+อัศจรรย์ = มหัศจรรย์"],["พยัญชนะสนธิ","พยัญชนะท้ายคำหน้าเปลี่ยนรูป","นิส+ภัย = นิรภัย · ทุส+ชน = ทุรชน · มนส+ธรรม = มโนธรรม"],["นิคหิตสนธิ","คำหน้าลงท้ายนิคหิต (สํ) เปลี่ยนเป็น ง ญ ณ น ม ตามวรรคคำหลัง","สํ+คม = สังคม · สํ+อาคม = สมาคม · สํ+ปทาน = สัมปทาน"]]},{"k":"pairs","items":[{"a":"สมาสธรรมดา (ชนกันเฉย ๆ)","b":"กาลเทศะ ยุทธวิธี ราชทินนาม ขีปนาวุธ: เขียนต่อกันเฉย ๆ ไม่มีเสียงกลืน"},{"a":"สมาสแบบสนธิ (กลืนเสียง)","b":"ราชูปโภค ธันวาคม มหัศจรรย์ ปรมินทร์ นเรศวร (นร+อิศวร)"}]},{"k":"oops","t":"ข้อ \"สนธิทุกคำ\" ให้ลองแยกคำ ถ้าแยกแล้วได้คำเดิมครบโดยไม่มีสระหายหรือเปลี่ยน = สมาสธรรมดา เช่น กาลเทศะ รัตติกาล อภิบาล ไม่ใช่สนธิ"}]},{"id":"plaeng","icon":"🔀","tone":"lil","title":"คำแผลง","big":"จ่าย→จำหน่าย","unit":"","sub":"เปลี่ยน/เพิ่มเสียง ได้คำใหม่ความหมายใกล้เดิม","ask":"คำแผลงเกิดจา