  ('b3-thai-lit', 'B3', false, 66, '{"group":"B3","topics":["B3-THAI"],"id":"b3-thai-lit","subtopics":["B3-THAI-LIT"],"icon":"📜","title":"วรรณคดี ① ยุคสมัย ผู้แต่ง & ยอดวรรณคดี","hub":"วรรณคดีไทย","hubSub":"สุโขทัย → รัตนโกสินทร์","intro":"หมวดที่มีข้อมากเป็นอันดับ 2 ของวิชาเอก และคนตอบถูกไม่ถึงครึ่ง: จับคู่เรื่อง-ผู้แต่ง-ยุค ให้แม่น","branches":[{"id":"sukho","icon":"🪨","tone":"pink","title":"สุโขทัย & อยุธยา","big":"ไตรภูมิพระร่วง","unit":"","must":true,"sub":"พญาลิไท · มหาชาติคำหลวง · ลิลิตพระลอ · จินดามณี","ask":"วรรณคดีสำคัญสมัยสุโขทัยและอยุธยา","blocks":[{"k":"table","head":["เรื่อง","ผู้แต่ง/สมัย","จุดเด่น"],"rows":[["ศิลาจารึกหลักที่ 1","พ่อขุนรามคำแหง (สุโขทัย)","หลักฐานอักษรไทยเก่าสุด"],["ไตรภูมิพระร่วง","พญาลิไท (สุโขทัย)","วรรณคดีพุทธศาสนา นรก-สวรรค์"],["ลิลิตโองการแช่งน้ำ","อยุธยาตอนต้น","ใช้ในพิธีถือน้ำพระพิพัฒน์สัตยา"],["ลิลิตยวนพ่าย","อยุธยาตอนต้น","เฉลิมพระเกียรติพระบรมไตรโลกนาถ"],["มหาชาติคำหลวง","สมัยพระบรมไตรโลกนาถ","เวสสันดรชาดก"],["ลิลิตพระลอ","อยุธยาตอนต้น","ยอดของลิลิต (วรรณคดีสโมสร)"],["สมุทรโฆษคำฉันท์","พระมหาราชครู · สมเด็จพระนารายณ์ · กรมพระปรมานุชิตชิโนรส (แต่งต่อจนจบ)","ยอดของคำฉันท์"],["จินดามณี","พระโหราธิบดี (สมเด็จพระนารายณ์)","แบบเรียนภาษาไทยเล่มแรก"],["กาพย์เห่เรือ · กาพย์ห่อโคลงประพาสธารทองแดง","เจ้าฟ้าธรรมธิเบศร (อยุธยาตอนปลาย)","กาพย์เห่เรือเป็นแบบแผนของบทเห่"]]}]},{"id":"ratta","icon":"🏯","tone":"mint","title":"ธนบุรี & รัตนโกสินทร์","big":"สุนทรภู่","unit":"","must":true,"hot":true,"sub":"รามเกียรติ์ · อิเหนา · สามก๊ก · พระอภัยมณี · ตะเลงพ่าย","ask":"วรรณคดีสำคัญสมัยรัตนโกสินทร์และผู้แต่ง","blocks":[{"k":"table","head":["เรื่อง","ผู้แต่ง"],"rows":[["บทละครรามเกียรติ์","สมเด็จพระเจ้าตากสินฯ (ธนบุรี) · รัชกาลที่ 1 (ฉบับสมบูรณ์)"],["บทละครเรื่องอิเหนา","รัชกาลที่ 2"],["สามก๊ก","เจ้าพระยาพระคลัง (หน)"],["ลิลิตตะเลงพ่าย","สมเด็จพระมหาสมณเจ้า กรมพระปรมานุชิตชิโนรส"],["พระอภัยมณี · นิราศภูเขาทอง","สุนทรภู่"],["สามัคคีเภทคำฉันท์","ชิต บุรทัต"],["มัทนะพาธา · หัวใจนักรบ · เวนิสวาณิช","รัชกาลที่ 6"],["พระราชพิธีสิบสองเดือน","รัชกาลที่ 5