  ('b3-thai-lit2', 'B3', false, 67, '{"group":"B3","topics":["B3-THAI"],"id":"b3-thai-lit2","subtopics":["B3-THAI-LIT"],"icon":"🌸","title":"วรรณคดี ② รส ภาพพจน์ & ไวพจน์","hub":"วรรณศิลป์","hubSub":"รส 4 · ภาพพจน์ · คำไวพจน์","branches":[{"id":"rasa","icon":"💗","tone":"pink","title":"รสวรรณคดีไทย","big":"4","unit":"รส","must":true,"sub":"เสาวรจนี · นารีปราโมทย์ · พิโรธวาทัง · สัลลาปังคพิสัย","ask":"รสวรรณคดีไทย 4 รส มีอะไรบ้าง","blocks":[{"k":"pairs","items":[{"a":"เสาวรจนี","b":"ชมความงาม (ตัวละคร บ้านเมือง ธรรมชาติ)"},{"a":"นารีปราโมทย์","b":"เกี้ยวพาราสี โอ้โลม แสดงความรัก"},{"a":"พิโรธวาทัง","b":"โกรธ ตัดพ้อ ประชดประชัน"},{"a":"สัลลาปังคพิสัย","b":"โศกเศร้า คร่ำครวญ"}]},{"k":"memo","t":"เสาว = งาม · นารี = หญิง (จีบ) · พิโรธ = โกรธ · สัลลาปัง = รำพันโศก"}]},{"id":"figure","icon":"🎨","tone":"mint","title":"ภาพพจน์","big":"เหมือน · เป็น","unit":"","must":true,"hot":true,"sub":"อุปมา = เหมือน · อุปลักษณ์ = เป็น/คือ","ask":"อุปมากับอุปลักษณ์ต่างกันอย่างไร","blocks":[{"k":"table","head":["ภาพพจน์","หลักสังเกต","ตัวอย่าง"],"rows":[["อุปมา","เปรียบด้วย เหมือน ดุจ ราว ดั่ง ปาน เพียง","หน้าเหมือนดวงจันทร์"],["อุปลักษณ์","เปรียบว่า \"เป็น/คือ\" หรือแทนกันเลย","พ่อแม่คือจันทรสุริยศรี"],["บุคคลวัต","ให้สิ่งไม่มีชีวิตทำอย่างคน","ดวงดาวกะพริบตาเรียกหา"],["อติพจน์","กล่าวเกินจริง","คิดถึงใจจะขาด · สิ้นท่านทั่วปฐพีมืดหมน"],["อวพจน์","กล่าวน้อยกว่าจริง","รอสักอึดใจ"],["สัทพจน์","เลียนเสียงธรรมชาติ","ฝนตกเปาะแปะ"],["นามนัย","ใช้ส่วนหนึ่งหรือสิ่งเกี่ยวข้องแทนทั้งหมด","เก้าอี้ (= ตำแหน่ง) · เมืองโอ่ง (= ราชบุรี)"],["ปฏิพากย์","คำขัดแย้งกันในข้อความเดียว","เลวบริสุทธิ์ · ความเงียบที่ดังที่สุด"],["สัญลักษณ์","ใช้สิ่งหนึ่งแทนความหมายที่รู้กัน","สีขาว = ความบริสุทธิ์ · นกพิราบ = สันติภาพ"]]},{"k":"oops","t":"\"ใครแทนพ่อแม่ได้ ไป่มีเลยท่าน คือจันทรสุริยศรี... สิ้นท่านทั่วปฐพี มืดหมน\" = อุปลักษณ์ (คือ) + อติพจน์ (ทั่วปฐพีมืด) ไม่มีบุคคลวัต"}]},{"id":"syn","icon":"🔁","tone":"sky","title":"คำไวพจน์","big":"วารี","unit":"= น้ำ","hot":true,"sub":"คำต่างรูป ความหมายเดียวกัน (คำพ้องความหมาย)"