  ('b3-thai-poet', 'B3', false, 68, '{"group":"B3","topics":["B3-THAI"],"id":"b3-thai-poet","subtopics":["B3-THAI-POET"],"icon":"🎼","title":"ฉันทลักษณ์","hub":"คำประพันธ์","hubSub":"กลอน · กาพย์ · โคลง · ฉันท์ · ร่าย","intro":"คนตอบถูกไม่ถึง 4 ใน 10 ข้อ: นับคำต่อวรรคก่อน แล้วค่อยดูครุ-ลหุ","branches":[{"id":"count","icon":"🔢","tone":"pink","title":"นับคำแยกประเภท","big":"11 · 16 · 28","unit":"ยานี ฉบัง สุรางค์","must":true,"hot":true,"sub":"ยานี 5/6 · ฉบัง 6/4/6 · สุรางคนางค์ 4×7","ask":"กาพย์ยานี ฉบัง สุรางคนางค์ วรรคละกี่คำ","blocks":[{"k":"table","head":["คำประพันธ์","คำต่อวรรค","สังเกต"],"rows":[["กาพย์ยานี 11","5 / 6","บาทละ 11 คำ"],["กาพย์ฉบัง 16","6 / 4 / 6","บาทละ 16 คำ"],["กาพย์สุรางคนางค์ 28","4 × 7 วรรค","บทละ 28 คำ"],["กลอนสุภาพ (กลอนแปด)","7–9 (นิยม 8)","บทละ 4 วรรค: สดับ รับ รอง ส่ง"],["โคลงสี่สุภาพ","บาทละ 5 + 2 (บาท 4: 5 + 4)","เอก 7 โท 4 · 30 คำ"],["ร่ายสุภาพ","วรรคละ 5","จบด้วยโคลงสองสุภาพ"]]},{"k":"oops","t":"\"พสุธาอากาศหวาดไหว (6) เนื้อนกตกใจ (4) ซุกซ่อนประหวั่นขวัญหนี (6)\" = 6/4/6 กาพย์ฉบัง → ตอบ \"กาพย์\" ข้อนี้คนตอบ \"โคลง\""}]},{"id":"klon","icon":"🎶","tone":"mint","title":"สัมผัสกลอนสุภาพ","big":"สดับ→รับ","unit":"","must":true,"sub":"ท้ายวรรค → คำที่ 3 หรือ 5 ของวรรคถัดไป","ask":"สัมผัสบังคับของกลอนสุภาพมีอะไรบ้าง","blocks":[{"k":"steps","items":[{"t":"คำท้ายวรรคสดับ → คำที่ 3 หรือ 5 ของวรรครับ"},{"t":"คำท้ายวรรครับ → คำท้ายวรรครอง"},{"t":"คำท้ายวรรครอง → คำที่ 3 หรือ 5 ของวรรคส่ง"},{"t":"คำท้ายวรรคส่ง → คำท้ายวรรครับของบทถัดไป (สัมผัสระหว่างบท)"}]},{"k":"table","head":["วรรค","เสียงท้ายวรรคที่นิยม"],"rows":[["สดับ","ได้ทุกเสียง (นิยมไม่ใช้สามัญ)"],["รับ","จัตวา (ห้ามสามัญ)"],["รอง","สามัญ หรือ ตรี"],["ส่ง","สามัญ หรือ ตรี"]]},{"k":"pairs","items":[{"a":"กาพย์ยานี: สัมผัส","b":"ท้ายวรรคแรก → คำที่ 3 วรรคสอง · ท้ายวรรคสอง → ท้ายวรรคสาม"},{"a":"กาพย์ฉบัง: สัมผัส","b":"ท้ายวรรคแรก → ท้ายวรรคสอง"}]}]},{"id":"khlong","icon":"📐","tone":"sky","title":"โคลงสี่สุภาพ","big":"เอก 7 โท 4","unit":"","must":true,"hot":true,"sub":"เอกโทษ · โทโทษ ใช้เมื่